// Current-state documentation facts (DOC-01). The counts and tables that the current pages state about the product are
// written from the code and the committed ledgers between markers, so a page cannot drift from what it describes:
//
//   <!-- fact:reviewed_families -->170<!-- /fact -->      one value in running text
//   <!-- doc-facts:tool-surface:begin (generated by npm run docs:index; do not edit) -->
//   ...
//   <!-- doc-facts:tool-surface:end -->                   a generated block
//
// Outside the markers it refuses what the 2026-10-08 review found typed by hand into current pages (R25): "B25 open",
// the retired single-label package count and its triples, and family, recipe, guide or tool counts, on every current
// page; only the dated narrative lines listed in historyLines keep the counts of their day.
//
//   node tools/doc-facts.mjs           write every marker from the code (after npm run build)
//   node tools/doc-facts.mjs --check   fail when a marker disagrees with the code or a ledger, or a page breaks a rule
//
// `npm run docs:index` writes and `npm run docs:index:check` checks them (tools/docs-index.mjs), so they run wherever the
// documentation index does: `npm run check`, the qualification fast gate, `npm run test:related` and the Docker build.
// The facts that need the built code are collected in a child process with a fixed environment: a developer's
// AMCP_PROVIDERS, AMCP_LINKEDIN_API_VERSION or MIRROR_FLAGS cannot change them, so Railway's Linux build computes the
// same bytes as a Windows checkout. It reads committed files and dist/ only, writes only the marked regions, and
// contacts nothing.
import fs from 'node:fs';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {fileURLToPath, pathToFileURL} from 'node:url';
import {manualStates, nativeStates, statusFile} from './package-status.mjs';
import {providerNames} from './acceptance/provider-access.mjs';
import {readMoves} from './docs-links.mjs';

const ledgerFile = 'docs/implementation/ACTION-CONTRACT-COVERAGE.json';
/** Every file that holds markers, with the inline facts it must hold (so deleting a marker cannot pass the check). */
export const factFiles = Object.freeze({
  'README.md': ['reviewed_families', 'campaign_recipes', 'mcp_guides', 'tools_writes', 'ledger_actions'],
  'docs/CURRENT-READINESS.md': ['reviewed_families', 'campaign_recipes', 'mcp_guides', 'tools_writes'],
  'docs/ADDING-A-REVIEWED-FAMILY.md': ['reviewed_families'],
  'docs/WORKSPACE-OPERATIONS.md': ['tools_read_only', 'tools_writes'],
  'docs/MICROSOFT-ADS.md': ['microsoft_actions', 'microsoft_mutations'],
  'docs/MEASUREMENT-AND-APPLE.md': ['apple_actions', 'apple_reviewed_writes'],
  'docs/DEPLOY-RAILWAY.md': ['tools_writes'],
  'docs/acceptance/WRITE-ACCEPTANCE.md': ['campaign_recipes'],
  'docs/review/ARCHITECTURE.md': ['reviewed_families'],
});
/** Each generated block and the one file it lives in. */
export const blockFiles = Object.freeze({
  'package-status': 'docs/CURRENT-READINESS.md',
  'provider-matrix': 'docs/CURRENT-READINESS.md',
  'tool-surface': 'docs/CURRENT-READINESS.md',
  'reviewed-families': 'docs/ADDING-A-REVIEWED-FAMILY.md',
  'oauth-platforms': 'docs/DEPLOY-RAILWAY.md',
  'measurement-writes': 'docs/MEASUREMENT-AND-APPLE.md',
});
/**
 * Pages that are not current pages although they sit beside them: the decision record is history and keeps the words
 * of its day. The dated reviews that sat here moved to docs/archive/ (DOC-03), and the redirect stub each left at its
 * old address (docs/moved.json) is no current page either: currentPages() leaves every stub out. Every other page
 * currentPages() returns (the guides, runbooks and references that describe the product as it is now) may not use the
 * retired status vocabulary outside a marker.
 */
export const historicalPages = Object.freeze([
  'docs/DECISIONS.md',
  // Generated from the ledger and the registries by their own tools; their own checks keep them current.
  'docs/CONTRACTS.md',
  'docs/DOCUMENT-KINDS.md',
  'docs/PROVIDER-ACCESS.md',
]);
/**
 * Dated narrative lines that keep a count of their day, by page: the count rules skip a line of that page containing
 * the quoted text (the status rules still apply to it). Each entry is history, never the product's size now, and an
 * entry whose text its page no longer holds is a problem, so the list cannot outlive its lines. Every other line of
 * every current page takes its family, recipe, guide and tool counts from a marker.
 */
export const historyLines = Object.freeze({
  // The re-baseline of the MCP evaluation after the wave 2 merges (2026-10-11).
  'docs/OPERATIONS.md': ['28 → 27 tools'],
  // The registry passes of September 2026, family by family.
  'docs/review/ARCHITECTURE.md': ['Pass 1 registered 41 families', '(57 families;', '(71 families;'],
});

const numberWord =
  '(?:\\d[\\d,]*|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty)';
/** Words of the single-label package status the three-axis status replaced (DOC-02, owner decision D25). */
export const statusRules = Object.freeze([
  {
    pattern: /\bB25 (?:conditional provider programs )?(?:remains |stays |is |still )*open\b/i,
    reason: 'B25 is partial, not open: state package status through docs/review/PACKAGE-STATUS.md',
  },
  {
    pattern: /\b\d+ implemented ?\/ ?\d+ partial\b/i,
    reason: 'the single-label package count is retired: link the three-axis package status instead',
  },
  {
    pattern: /(?<!implemented ?\/ ?)\b\d+ partial\b/i,
    reason: 'a hand-typed package count: link the three-axis package status instead',
  },
  {
    pattern: /\b1\d ?\/ ?1\d ?\/ ?\d\b/,
    reason: 'a single-label package triple: link the three-axis package status instead',
  },
]);
/** Counts a reader takes the product's size from: they come from a fact marker (or are left out). */
export const countRules = Object.freeze([
  {
    // A number never ends in its group separator: "RFC 7009, family revoke" names no count.
    pattern: /\b\d(?:[\d,]*\d)?\s+(?:registered\s+|reviewed\s+)*(?:write\s+)?famil(?:y|ies)\b/i,
    reason: 'a hand-typed family count: use <!-- fact:reviewed_families -->',
  },
  {
    pattern: new RegExp(
      // One free word may stand between the number and the noun ("three specified campaign types").
      '\\b' +
        numberWord +
        '\\s+(?:[a-z-]+\\s+)?(?:guided\\s+)?(?:campaign\\s+)?(?:recipes|campaign types|launch packs)\\b',
      'i',
    ),
    reason: 'a hand-typed recipe count: use <!-- fact:campaign_recipes -->',
  },
  {
    pattern: new RegExp(
      '\\b' + numberWord + '\\s+(?:campaign/reporting\\s+|MCP\\s+|workflow\\s+|campaign\\s+)?guides\\b',
      'i',
    ),
    reason: 'a hand-typed guide count: use <!-- fact:mcp_guides -->',
  },
  {
    pattern: /\b\d+\s+(?:MCP\s+)?tools\b/i,
    reason: 'a hand-typed tool count: use <!-- fact:tools_writes --> or <!-- fact:tools_read_only -->',
  },
]);

const inlineMarker = /<!-- fact:([a-z0-9_]+) -->([^<\n]*)<!-- \/fact -->/g,
  blockMarker =
    /<!-- doc-facts:([a-z0-9-]+):begin \(generated by npm run docs:index; do not edit\) -->\n([\s\S]*?)<!-- doc-facts:\1:end -->/g,
  stray = /<!-- (?:\/?fact\b|doc-facts:)/;
const begin = name => '<!-- doc-facts:' + name + ':begin (generated by npm run docs:index; do not edit) -->';
const grouped = n => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
const cell = v => String(v).replace(/\|/g, '\\|');
const yes = v => (v ? 'yes' : 'no');
const list = items => (items.length < 3 ? items.join(' and ') : items.slice(0, -1).join(', ') + ' and ' + items.at(-1));

/**
 * The facts that need the built code, from a child process with a fixed environment. Only what the operating system
 * needs to start Node is passed on; no AMCP_, MIRROR_ or provider setting reaches the child.
 */
export function collectCodeFacts(root) {
  const env = {TZ: 'UTC'};
  for (const name of ['PATH', 'Path', 'PATHEXT', 'SystemRoot', 'SYSTEMROOT', 'windir', 'TEMP', 'TMP', 'TMPDIR'])
    if (process.env[name] !== undefined) env[name] = process.env[name];
  const run = spawnSync(process.execPath, [fileURLToPath(import.meta.url), '--collect', root], {
    cwd: root,
    env,
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
    windowsHide: true,
  });
  if (run.status !== 0)
    throw Error(
      'Documentation facts could not be collected from dist/ (run npm run build first): ' +
        String(run.stderr || run.error?.message || 'exit ' + run.status)
          .trim()
          .split('\n')
          .slice(-3)
          .join(' '),
    );
  return JSON.parse(run.stdout);
}

/** Runs in the child: imports the built modules and lists the tool surface as an MCP client receives it. */
async function collectInChild(root) {
  const load = file => import(pathToFileURL(path.join(root, file)).href);
  const [
    {Store},
    {Registry},
    {MirrorService},
    {NativeTransport},
    {createMcpServer},
    {reviewedFamilies},
    {campaignRecipes},
    {guidanceResources},
    adapters,
    {effectiveProviderContract},
    {providerSunsets},
    {microsoftActions},
    {appleActions},
    oauth,
    {appClient},
  ] = await Promise.all(
    [
      'dist/src/store.js',
      'dist/src/catalog.js',
      'dist/src/service.js',
      'dist/src/transport.js',
      'dist/server/mcp.js',
      'dist/src/reviewed-families.js',
      'dist/src/campaign-recipes.js',
      'dist/src/guidance.js',
      'dist/src/provider-adapters.js',
      'dist/src/provider-contracts.js',
      'dist/src/provider-sunsets.js',
      'dist/src/microsoft-native.js',
      'dist/src/apple-native.js',
      'dist/server/platform-oauth.js',
      'dist/src/app-credentials.js',
    ].map(load),
  );
  const {Client} = await import('@modelcontextprotocol/sdk/client/index.js'),
    {InMemoryTransport} = await import('@modelcontextprotocol/sdk/inMemory.js');
  const surface = async allowWrites => {
    const store = new Store(':memory:', Buffer.alloc(32, 41).toString('base64')),
      actor = {tenantId: 'documentation-facts', userId: 'owner', role: 'admin'};
    store.ensureTenant(actor.tenantId);
    const transport = new NativeTransport(async () => {
      throw Error('Documentation facts make no provider request.');
    });
    const policy = allowWrites ? {allowWrites: true, maxBudgetChange: 0, requireBeforeState: true} : undefined,
      service = new MirrorService(new Registry(), store, transport, undefined, policy),
      server = createMcpServer(service, actor),
      client = new Client({name: 'amcp-documentation-facts', version: '1'}),
      [a, b] = InMemoryTransport.createLinkedPair();
    await Promise.all([server.connect(b), client.connect(a)]);
    try {
      const listed = await client.listTools();
      return {
        bytes: Buffer.byteLength(JSON.stringify(listed)),
        tools: listed.tools.map(t => ({
          name: t.name,
          title: t.title ?? null,
          readOnlyHint: t.annotations?.readOnlyHint ?? null,
          destructiveHint: t.annotations?.destructiveHint ?? null,
          idempotentHint: t.annotations?.idempotentHint ?? null,
          openWorldHint: t.annotations?.openWorldHint ?? null,
        })),
      };
    } finally {
      await client.close();
      await server.close();
      store.close();
    }
  };
  const registry = new Registry();
  // The website platforms' OAuth setup, as PlatformOAuth resolves it for an environment that names only these values.
  const web = {origin: 'https://amcp.shop'},
    configured = (p, env) => new oauth.PlatformOAuth(web, env).config(p).configured,
    pair = stem => ({['AMCP_' + stem + '_CLIENT_ID']: 'id', ['AMCP_' + stem + '_CLIENT_SECRET']: 'secret'}),
    google = {AMCP_GOOGLE_CLIENT_ID: 'google', AMCP_GOOGLE_CLIENT_SECRET: 'google-secret'};
  const platforms = oauth.platforms.map(p => ({
    id: p.id,
    name: p.name,
    stem: p.env,
    callback: p.authType ? null : new oauth.PlatformOAuth(web, {}).config(p).redirectUri,
    shares_google: appClient(p.env, google).clientId === 'google',
    shares_google_when_approved: appClient(p.env, {...google, AMCP_GBP_API_APPROVED: 'true'}).clientId === 'google',
    configured_with_pair: configured(p, pair(p.env)),
    configured_with_developer_token: configured(p, {
      ...pair(p.env),
      ['AMCP_' + p.env + '_DEVELOPER_TOKEN']: 'token',
    }),
    configured_with_signing_key: configured(p, {
      ['AMCP_' + p.env + '_CLIENT_ID']: 'id',
      ['AMCP_' + p.env + '_TEAM_ID']: 'team',
      ['AMCP_' + p.env + '_KEY_ID']: 'key',
      ['AMCP_' + p.env + '_PRIVATE_KEY']: 'private',
    }),
    user_agent_setting:
      p.id === 'reddit' &&
      new oauth.PlatformOAuth(web, {AMCP_REDDIT_USER_AGENT: 'probe/1'}).redditUserAgent() === 'probe/1',
  }));
  return {
    tools: {read_only: await surface(false), writes: await surface(true)},
    families: reviewedFamilies().map(f => ({name: f.name, provider: adapters.familyProvider(f.name)?.id ?? null})),
    recipes: campaignRecipes.map(r => ({id: r.id, platform: r.platform})),
    guides: guidanceResources.map(g => g.uri),
    providers: adapters.providerAdapters.map(a => {
      const contract = effectiveProviderContract(a.id),
        version = contract?.api_version ?? null,
        sunset = providerSunsets.find(s => s.provider === a.id && s.version === version);
      return {
        id: a.id,
        gateway: a.gateway,
        status: a.status,
        reason: a.parked?.reason ?? null,
        api_version: version,
        sunset: sunset ? {date: sunset.sunset ?? null, basis: sunset.basis} : null,
      };
    }),
    microsoft: {actions: microsoftActions.length, mutations: microsoftActions.filter(x => !x.read_only).length},
    apple: {actions: appleActions.length},
    captured: {
      tools: registry.data.tools.length,
      gateways: registry.data.catalogs.length,
      schemas: registry.data.tools.reduce((n, t) => n + (t.operations?.length ?? 0), 0),
    },
    platforms,
  };
}

/** Facts read from committed files only: the action ledger and the package status. */
function fileFacts(root) {
  const ledger = JSON.parse(fs.readFileSync(path.join(root, ledgerFile), 'utf8')),
    status = JSON.parse(fs.readFileSync(path.join(root, statusFile), 'utf8'));
  return {
    ledger: {
      gateways: ledger.summary.map(g => ({gateway: g.gateway, actions: g.actions, counts: g.counts})),
      actions: ledger.acceptance_layers.catalog,
      reviewed: ledger.actions
        .filter(a => a.status === 'reviewed_write_family')
        .map(a => ({gateway: a.gateway, action: a.action, implementation: a.implementation})),
      unsupported: ledger.actions
        .filter(a => a.status === 'provider_unsupported')
        .map(a => ({gateway: a.gateway, action: a.action})),
    },
    status,
  };
}

const sunsetText = s =>
  !s?.date ? 'no date recorded' : s.date + (s.basis === 'official' ? ' (published)' : ' (support period)');
const providerName = id => providerNames[id] ?? id;
const reviewedOf = (facts, gateway) =>
  facts.ledger.gateways.find(g => g.gateway === gateway)?.counts?.reviewed_write_family ?? 0;

/** The value of every inline fact. */
export function inlineFacts(facts) {
  const writes = facts.tools.writes,
    readOnly = facts.tools.read_only,
    byPlatform = new Map();
  for (const r of facts.recipes) byPlatform.set(r.platform, (byPlatform.get(r.platform) ?? 0) + 1);
  const platformNames = {microsoft: 'Microsoft Advertising', google: 'Google Ads'};
  const parked = facts.providers.filter(p => p.status === 'parked');
  return {
    reviewed_families: grouped(facts.families.length),
    campaign_recipes: grouped(facts.recipes.length),
    campaign_recipe_platforms: list(
      [...byPlatform]
        .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
        .map(([platform, n]) => (platformNames[platform] ?? providerName(platform)) + ' ' + n),
    ),
    mcp_guides: grouped(facts.guides.length),
    tools_read_only: grouped(readOnly.tools.length),
    tools_writes: grouped(writes.tools.length),
    tools_list_bytes_read_only: grouped(readOnly.bytes),
    tools_list_bytes_writes: grouped(writes.bytes),
    providers: grouped(facts.providers.length),
    providers_active: grouped(facts.providers.length - parked.length),
    providers_parked: list(parked.map(p => providerName(p.id))),
    website_platforms: grouped(facts.platforms.length),
    ledger_actions: grouped(facts.ledger.actions),
    ledger_reviewed_writes: grouped(facts.ledger.reviewed.length),
    microsoft_actions: grouped(facts.microsoft.actions),
    microsoft_mutations: grouped(facts.microsoft.mutations),
    apple_actions: grouped(facts.apple.actions),
    apple_reviewed_writes: grouped(reviewedOf(facts, 'apple_ads_native_action')),
    captured_tools: grouped(facts.captured.tools),
    captured_gateways: grouped(facts.captured.gateways),
    captured_schemas: grouped(facts.captured.schemas),
    packages_source_met: grouped(facts.status.packages.filter(p => p.source.met).length),
    packages_total: grouped(facts.status.packages.length),
  };
}

function packageStatusBlock(facts) {
  const packages = facts.status.packages,
    count = (pick, values) => values.map(v => v + ' ' + packages.filter(p => pick(p) === v).length).join(' · ');
  const lines = [
    'Generated from [package-status.json](review/package-status.json), status as of ' + facts.status.as_of + '.',
    '[Package status](review/PACKAGE-STATUS.md) has every remainder and the test files each package cites.',
    '',
    '| Axis | Count |',
    '|---|---|',
    '| Source acceptance (of ' +
      packages.length +
      ') | ' +
      count(p => (p.source.met ? 'met' : 'not met'), ['met', 'not met']) +
      ' |',
    '| Native/live acceptance | ' + count(p => p.native.state, nativeStates) + ' |',
    '| Manual/deployed acceptance | ' + count(p => p.manual.state, manualStates) + ' |',
    '',
    '| Package | Deliverable | Source | Native | Manual |',
    '|---|---|---|---|---|',
  ];
  for (const p of packages)
    lines.push(
      '| ' +
        [
          p.id,
          cell(p.title),
          p.source.met ? 'met' : 'not met: ' + cell(p.source.gap),
          p.native.state.replaceAll('_', ' '),
          p.manual.state.replaceAll('_', ' '),
        ].join(' | ') +
        ' |',
    );
  return lines;
}

function providerMatrixBlock(facts) {
  const families = new Map();
  for (const f of facts.families) families.set(f.provider, (families.get(f.provider) ?? 0) + 1);
  const lines = [
    'Generated from the provider adapter registry (`src/provider-adapters.ts`), the provider contracts at the version',
    'AMCP sends by default (`src/provider-contracts.ts`), the sunset registry (`src/provider-sunsets.ts`), the',
    'reviewed-family registry and the [action ledger](implementation/ACTION-CONTRACT-COVERAGE.json). A parked provider',
    'is offered only where `AMCP_PROVIDERS` names it.',
    '',
    '| Provider | Gateway | Status | API version | Version ends | Reviewed families | Ledger actions | Reviewed write actions |',
    '|---|---|---|---|---|---:|---:|---:|',
  ];
  for (const p of facts.providers) {
    const ledger = facts.ledger.gateways.find(g => g.gateway === p.gateway);
    lines.push(
      '| ' +
        [
          providerName(p.id),
          '`' + p.gateway + '`',
          p.status === 'parked' ? 'parked (' + p.reason + ')' : 'active',
          p.api_version ? cell(p.api_version) : '—',
          p.api_version ? sunsetText(p.sunset) : '—',
          grouped(families.get(p.id) ?? 0),
          ledger ? grouped(ledger.actions) : '—',
          ledger ? grouped(ledger.counts.reviewed_write_family ?? 0) : '—',
        ].join(' | ') +
        ' |',
    );
  }
  return lines;
}

function toolSurfaceBlock(facts) {
  const {read_only: readOnly, writes} = facts.tools,
    names = [...new Set([...writes.tools.map(t => t.name), ...readOnly.tools.map(t => t.name)])];
  const lines = [
    'Generated from `tools/list` as an MCP client receives it, with `MIRROR_FLAGS` and `AMCP_PROVIDERS` unset.',
    'A read-only deployment lists ' +
      readOnly.tools.length +
      ' tools (' +
      grouped(readOnly.bytes) +
      ' bytes of `tools/list`),',
    'and a deployment with reviewed writes ' + writes.tools.length + ' (' + grouped(writes.bytes) + ' bytes).',
    'The hints tell clients when to ask the user; every safeguard stays on the server (`src/tool-annotations.ts`).',
    'Where the two deployments differ, the read-only value follows in brackets.',
    '',
    '| Tool | Title | Read-only | Destructive | Idempotent | Open world |',
    '|---|---|---|---|---|---|',
  ];
  for (const name of names) {
    const w = writes.tools.find(t => t.name === name),
      r = readOnly.tools.find(t => t.name === name);
    const value = key => {
      const shown = w ? (key === 'title' ? w.title : yes(w[key])) : 'not listed',
        other = r ? (key === 'title' ? r.title : yes(r[key])) : 'not listed';
      return cell(shown) + (other === shown ? '' : ' (' + cell(other) + ')');
    };
    lines.push(
      '| `' +
        name +
        '` | ' +
        ['title', 'readOnlyHint', 'destructiveHint', 'idempotentHint', 'openWorldHint'].map(value).join(' | ') +
        ' |',
    );
  }
  return lines;
}

function familiesBlock(facts) {
  const lines = [
    'Generated from `src/reviewed-families.ts` and the provider adapter registry: each family belongs to the provider',
    'whose family prefix its name starts with. A parked provider keeps its families registered; the listings leave them',
    'out until `AMCP_PROVIDERS` offers it.',
    '',
    '| Provider | Status | Families | Names |',
    '|---|---|---:|---|',
  ];
  for (const p of facts.providers) {
    const names = facts.families.filter(f => f.provider === p.id).map(f => '`' + f.name + '`');
    if (!names.length) continue;
    lines.push(
      '| ' +
        [providerName(p.id), p.status === 'parked' ? 'parked' : 'active', names.length, names.join(', ')].join(' | ') +
        ' |',
    );
  }
  const orphans = facts.families.filter(f => !f.provider);
  if (orphans.length) throw Error('Reviewed families without a provider: ' + orphans.map(f => f.name).join(', '));
  return lines;
}

function platformsBlock(facts) {
  const lines = [
    'Generated from the website platforms (`platforms` in `server/platform-oauth.ts`) and their client lookup',
    '(`appClient` in `src/app-credentials.ts`). Replace the origin for another deployment; Settings shows each callback',
    'of the running deployment. Every platform but Apple Ads also takes `AMCP_<STEM>_SCOPES`, which replaces its default',
    'scopes.',
    '',
    '| Platform | Callback | Client variables | When both are unset | Also |',
    '|---|---|---|---|---|',
  ];
  for (const p of facts.platforms) {
    const also = [];
    if (!p.configured_with_pair) {
      if (!p.configured_with_developer_token)
        throw Error('Documentation facts: ' + p.id + ' needs more than its client pair; describe it here first.');
      also.push('`AMCP_' + p.stem + '_DEVELOPER_TOKEN` (required)');
    }
    if (p.configured_with_signing_key)
      also.push(
        'or `AMCP_' +
          p.stem +
          '_TEAM_ID`, `AMCP_' +
          p.stem +
          '_KEY_ID` and `AMCP_' +
          p.stem +
          '_PRIVATE_KEY` instead of the secret',
      );
    if (p.user_agent_setting) also.push('`AMCP_' + p.stem + '_USER_AGENT` (optional; a default names AMCP)');
    lines.push(
      '| ' +
        [
          p.name,
          p.callback ? '`' + p.callback + '`' : 'none: server-side client credentials',
          '`AMCP_' + p.stem + '_CLIENT_ID`, `AMCP_' + p.stem + '_CLIENT_SECRET`',
          p.shares_google && p.stem !== 'GOOGLE'
            ? 'the Google client (`AMCP_GOOGLE_CLIENT_ID`)'
            : p.shares_google_when_approved && p.stem !== 'GOOGLE'
              ? 'the Google client, once `AMCP_GBP_API_APPROVED=true`'
              : '—',
          also.join('; ') || '—',
        ].join(' | ') +
        ' |',
    );
  }
  return lines;
}

function measurementBlock(facts) {
  const gateways = [
    ['ga4_native_action', 'Google Analytics 4'],
    ['gtm_native_action', 'Google Tag Manager'],
    ['google_search_console_native_action', 'Google Search Console'],
    ['apple_ads_native_action', 'Apple Ads'],
  ];
  const lines = [
    'Generated from the [action ledger](implementation/ACTION-CONTRACT-COVERAGE.json), which `npm run contracts:actions`',
    'builds from the reviewed families: each reviewed write action, grouped by the module that implements it, and what',
    'the provider no longer supports.',
    '',
    '| Gateway | Ledger actions | By class |',
    '|---|---:|---|',
  ];
  for (const [gateway, name] of gateways) {
    const g = facts.ledger.gateways.find(x => x.gateway === gateway);
    if (!g) throw Error('Documentation facts: the ledger has no ' + gateway + '.');
    lines.push(
      '| ' +
        name +
        ' (`' +
        gateway +
        '`) | ' +
        grouped(g.actions) +
        ' | ' +
        Object.entries(g.counts)
          .map(([k, n]) => k.replaceAll('_', ' ') + ' ' + n)
          .join(' · ') +
        ' |',
    );
  }
  lines.push('');
  for (const [gateway, name] of gateways) {
    const byModule = new Map();
    for (const a of facts.ledger.reviewed.filter(a => a.gateway === gateway))
      byModule.set(a.implementation, [...(byModule.get(a.implementation) ?? []), a.action]);
    for (const [module, actions] of [...byModule].sort((a, b) => a[0].localeCompare(b[0])))
      lines.push(
        '- ' +
          name +
          ', `' +
          module +
          '` (' +
          actions.length +
          '): ' +
          actions.map(a => '`' + a + '`').join(', ') +
          '.',
      );
    const unsupported = facts.ledger.unsupported.filter(a => a.gateway === gateway).map(a => '`' + a.action + '`');
    if (unsupported.length)
      lines.push('- ' + name + ', no longer supported by the provider (refused): ' + unsupported.join(', ') + '.');
  }
  return lines;
}

/** Every generated block's lines, by name. */
export function renderBlocks(facts) {
  return {
    'package-status': packageStatusBlock(facts),
    'provider-matrix': providerMatrixBlock(facts),
    'tool-surface': toolSurfaceBlock(facts),
    'reviewed-families': familiesBlock(facts),
    'oauth-platforms': platformsBlock(facts),
    'measurement-writes': measurementBlock(facts),
  };
}

/** The text with every marker replaced by its current value, and the problems found (unknown or misplaced markers). */
export function applyFacts(text, file, values, blocks) {
  const problems = [],
    seen = new Set(),
    blocksSeen = new Set();
  let out = text.replace(blockMarker, (whole, name) => {
    if (!blocks[name]) {
      problems.push(file + ': unknown generated block ' + name + '.');
      return whole;
    }
    if (blockFiles[name] !== file)
      problems.push(file + ': the ' + name + ' block belongs in ' + blockFiles[name] + '.');
    if (blocksSeen.has(name)) problems.push(file + ': the ' + name + ' block appears twice.');
    blocksSeen.add(name);
    return begin(name) + '\n' + blocks[name].join('\n') + '\n<!-- doc-facts:' + name + ':end -->';
  });
  out = out.replace(inlineMarker, (whole, name) => {
    if (values[name] === undefined) {
      problems.push(file + ': unknown fact ' + name + '.');
      return whole;
    }
    seen.add(name);
    return '<!-- fact:' + name + ' -->' + values[name] + '<!-- /fact -->';
  });
  // A marker the patterns did not match (a typo, an unterminated block, a value on several lines) is a problem too.
  const unmatched = out.replace(inlineMarker, '').replace(blockMarker, '');
  if (stray.test(unmatched)) problems.push(file + ': a malformed documentation fact marker.');
  for (const name of factFiles[file] ?? [])
    if (!seen.has(name)) problems.push(file + ': the fact ' + name + ' is missing (it must come from a marker).');
  for (const [name, home] of Object.entries(blockFiles))
    if (home === file && !blocksSeen.has(name)) problems.push(file + ': the generated block ' + name + ' is missing.');
  return {text: out, problems};
}

/**
 * Problems of one page's text outside its markers under the given rules (line numbers are the page's own). A line that
 * contains one of `skip` (the page's historyLines, for the count rules) is not checked.
 */
export function lintText(text, file, rules, skip = []) {
  const outside = text
      .replace(blockMarker, block => '\n'.repeat(block.split('\n').length - 1))
      .replace(inlineMarker, ''),
    problems = [];
  outside.split('\n').forEach((line, i) => {
    if (skip.some(part => line.includes(part))) return;
    for (const rule of rules) {
      const match = rule.pattern.exec(line);
      if (match) problems.push(file + ':' + (i + 1) + ': "' + match[0] + '" — ' + rule.reason + '.');
    }
  });
  return problems;
}

/**
 * The current pages, from the repository tree: the root README, the guides and the current engineering pages, without
 * the historical pages and the redirect stubs of moved documents (docs/moved.json).
 */
export function currentPages(root) {
  const {moves} = readMoves(root);
  const markdown = dir =>
    fs.existsSync(path.join(root, dir))
      ? fs
          .readdirSync(path.join(root, dir), {recursive: true})
          .map(f => String(f).replaceAll('\\', '/'))
          .filter(f => f.endsWith('.md'))
          .map(f => dir + '/' + f)
      : [];
  const top = fs
    .readdirSync(path.join(root, 'docs'))
    .filter(f => f.endsWith('.md'))
    .map(f => 'docs/' + f);
  return [
    'README.md',
    ...top,
    ...markdown('docs/acceptance'),
    ...markdown('docs/owner'),
    'docs/review/ARCHITECTURE.md',
    'docs/review/THREAT-MODEL.md',
    ...markdown('Skills/amcp-campaign-builder'),
  ]
    .filter(f => !historicalPages.includes(f) && !moves.has(f) && fs.existsSync(path.join(root, f)))
    .sort();
}

/** Every AMCP_<STEM>_CLIENT_ID and _CLIENT_SECRET the website platforms read that .env.example does not name. */
export function environmentProblems(root, facts) {
  const example = fs.readFileSync(path.join(root, '.env.example'), 'utf8'),
    named = new Set([...example.matchAll(/^#?\s*(AMCP_[A-Z0-9_]+)=/gm)].map(m => m[1])),
    wanted = new Set();
  for (const p of facts.platforms)
    for (const suffix of ['CLIENT_ID', 'CLIENT_SECRET']) wanted.add('AMCP_' + p.stem + '_' + suffix);
  // Literal client variables read anywhere in the server and the core (social sign-in, the Business Profile pair).
  for (const dir of ['server', 'src'].filter(d => fs.existsSync(path.join(root, d))))
    for (const file of fs.readdirSync(path.join(root, dir), {recursive: true}).map(String))
      if (file.endsWith('.ts'))
        for (const m of fs.readFileSync(path.join(root, dir, file), 'utf8').matchAll(/\bAMCP_[A-Z0-9_]+_CLIENT_ID\b/g))
          wanted.add(m[0]);
  return [...wanted]
    .filter(name => !named.has(name))
    .sort()
    .map(name => '.env.example does not name ' + name + ', which the server reads.');
}

/** Checks (or, with write, rewrites) every marker and applies the rules; returns the problems and the changed files. */
export function docFacts(root, {write = false, facts} = {}) {
  facts ??= {...collectCodeFacts(root), ...fileFacts(root)};
  const values = inlineFacts(facts),
    blocks = renderBlocks(facts),
    problems = [],
    changed = [];
  for (const file of Object.keys(factFiles)) {
    const target = path.join(root, file);
    if (!fs.existsSync(target)) {
      problems.push(file + ' does not exist.');
      continue;
    }
    // Compared as committed (.gitattributes: eol=lf), so a working copy with CRLF line ends is not called stale.
    const before = fs.readFileSync(target, 'utf8').replaceAll('\r\n', '\n'),
      result = applyFacts(before, file, values, blocks);
    problems.push(...result.problems);
    if (result.text !== before) {
      changed.push(file);
      if (write && !result.problems.length) fs.writeFileSync(target, result.text);
      else if (!write)
        problems.push(file + ' states facts the code no longer has. Run npm run build, then npm run docs:index.');
    }
  }
  const pages = currentPages(root);
  for (const file of pages) {
    const text = fs.readFileSync(path.join(root, file), 'utf8').replaceAll('\r\n', '\n');
    problems.push(...lintText(text, file, statusRules));
    problems.push(...lintText(text, file, countRules, historyLines[file]));
  }
  // An exemption may not outlive its line: its page must still be a current page that holds the quoted text.
  for (const [file, parts] of Object.entries(historyLines)) {
    if (!fs.existsSync(path.join(root, file))) continue;
    const text = fs.readFileSync(path.join(root, file), 'utf8').replaceAll('\r\n', '\n');
    for (const part of parts)
      if (!pages.includes(file) || !text.includes(part))
        problems.push(
          file +
            ': historyLines in tools/doc-facts.mjs names "' +
            part +
            '", which is no line of this current page any more; remove it.',
        );
  }
  problems.push(...environmentProblems(root, facts));
  return {problems, changed, facts};
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv[2] === '--collect') process.stdout.write(JSON.stringify(await collectInChild(process.argv[3])));
  else {
    const root = fileURLToPath(new URL('..', import.meta.url)),
      check = process.argv.includes('--check'),
      {problems, changed} = docFacts(root, {write: !check});
    if (problems.length) {
      console.error('Documentation facts: ' + problems.join('\n'));
      process.exitCode = 1;
    } else
      console.log(
        check
          ? 'Documentation facts are current in ' + Object.keys(factFiles).length + ' pages.'
          : 'Documentation facts written' + (changed.length ? ': ' + changed.join(', ') : ' (no change)') + '.',
      );
  }
}
